CREATE OR REPLACE FUNCTION public.stats_messages_tsvector_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        BEGIN
            NEW.text_search := to_tsvector(
                'simple',
                COALESCE(NEW.text, '') || ' ' || COALESCE(NEW.caption, '')
            );
            RETURN NEW;
        END;
        $function$
